120	        headers.setLocation(UriComponentsBuilder.newInstance()
121	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
122	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
123	    }
124	
125	    /**
126	     * Build the customer code for a newly created owner, formatted {@code '<LAST3>-<NNNN>'}
127	     * where LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
128	     * global 4-digit zero-padded sequence equal to one more than the current number of owners
129	     * (e.g. {@code 'SMI-0007'}).
130	     */
131	    private String nextCustomerCode(String lastName) {
132	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
133	        int sequence = this.clinicService.findAllOwners().size() + 1;
134	        return String.format("%s-%04d", last3, sequence);
135	    }
136	
137	    /**
138	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
139	     * cannot form a valid E.164 number.
140	     *
141	     * <p>A leading '+' and country code are kept when present; otherwise country code
142	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
143	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
144	     * carry 8 to 15 digits after the '+'.
145	     */
146	    private String toE164(String telephone) {
147	        if (telephone == null) {
148	            return null;
149	        }
150	        boolean hasCountryCode = telephone.trim().startsWith("+");
151	        String digits = telephone.replaceAll("\\D", "");
152	        String e164;
153	        if (hasCountryCode) {
154	            e164 = digits;
155	        } else {
156	            if (digits.startsWith("0")) {
157	                digits = digits.substring(1);
158	            }
159	            e164 = "61" + digits;
160	        }
161	        if (e164.length() < 8 || e164.length() > 15) {
162	            return null;
163	        }
164	        return "+" + e164;
165	    }
