167	    /**
168	     * Whether any existing owner already holds the given telephone number. Both the
169	     * candidate and each stored number are compared in E.164 form, so the check does not
170	     * depend on how each was originally formatted.
171	     */
172	    private boolean isTelephoneInUse(String telephone) {
173	        return this.clinicService.findAllOwners().stream()
174	            .map(Owner::getTelephone)
175	            .filter(Objects::nonNull)
176	            .map(this::toE164)
177	            .filter(Objects::nonNull)
178	            .anyMatch(telephone::equals);
